@@ -0,0 +1,61 @@
+# Auth0 Tenant General Settings
+resource "auth0_tenant" "main" {
+  friendly_name         = "Alfredo's Auth0"
+  idle_session_lifetime = 2
+  session_lifetime      = 2
+
+  customize_mfa_in_postlogin_action = true
+}
+
+# Attack Protection Settings
+resource "auth0_attack_protection" "main" {
+  breached_password_detection {
+    enabled                      = true
+    method                       = "standard"
+    shields                      = ["block", "user_notification", "admin_notification"]
+    admin_notification_frequency = ["immediately"]
+  }
+
+  brute_force_protection {
+    enabled      = true
+    max_attempts = 5
+    shields      = ["block"]
+  }
+
+  suspicious_ip_throttling {
+    enabled = true
+    shields = ["block", "admin_notification"]
+
+    pre_login {
+      max_attempts = 50
+    }
+
+    pre_user_registration {
+      max_attempts = 50
+    }
+  }
+}
+
+# Configure MFA (WebAuthn Biometrics + recovery codes) via Auth0 Post-Login Action
+resource "auth0_action" "mfa" {
+  name = "Enforce WebAuthn MFA with Recovery Codes Fallback"
+
+  supported_triggers {
+    id      = "post-login"
+    version = "v3"
+  }
+
+  code = file("${path.module}/actions/mfa.js")
+
+  runtime = "node22"
+  deploy  = true
+}

